'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var pow = require( '@stdlib/math/base/special/pow' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// MAIN //

/**
* Returns a function for evaluating the cumulative distribution function (CDF) for a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d`.
*
* @param {PositiveNumber} c - first shape parameter
* @param {PositiveNumber} d - second shape parameter
* @returns {Function} CDF
*
* @example
* var cdf = factory( 0.5, 0.5 );
*
* var y = cdf( 0.8 );
* // returns ~0.687
*
* y = cdf( 0.3 );
* // returns ~0.595
*/
function factory( c, d ) {
	if (
		isnan( c ) ||
		isnan( d ) ||
		c <= 0.0 ||
		d <= 0.0
	) {
		return constantFunction( NaN );
	}
	return cdf;

	/**
	* Evaluates the cumulative distribution function (CDF) for a Burr (type III) distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {Probability} evaluated CDF
	*
	* @example
	* var y = cdf( 2.0 );
	* // returns <number>
	*/
	function cdf( x ) {
		if ( isnan( x ) || x <= 0.0 ) {
			return NaN;
		}
		return pow( 1 + pow( x, -c ), -d );
	}
}


// EXPORTS //

module.exports = factory;
